#include "domain/longstride.hpp"
#include "domain/thistletail.hpp"
#include "domain/hero_autonomy.hpp"
#include "domain/lifecycle.hpp"
#include "engine/native_population_registry.hpp"
#include "domain/next_life.hpp"
#include <iostream>
using namespace stalthos;
using namespace stalthos::fauna;
static void require(bool b,const char* why){if(!b)throw std::runtime_error(why);}
int main(){try{
 require(domain::playableSpecies("Longstride")==HeroSpecies::Longstride,"fifth validated actual species");needs::NeedsCore own(HeroSpecies::Longstride);Lifecycle life(HeroSpecies::Longstride);life.advance({0,2000});require(life.stage()==LifeStage::Juvenile && own.species()==life.species(),"actual selected profile components");
 domain::CarrionPatch carrion;const Vec3 food{carrion.x,2,carrion.z};require(carrion.sensed({carrion.x-6,2,carrion.z},2,1) && !carrion.sensed({carrion.x+32,2,carrion.z},2,1),"body-only food sense bounded");require(!carrion.sensed(food,2,0),"depleted no sensing");require(carrion.eligible(food,2,true,true) && !carrion.eligible(food,2,false,true) && !carrion.eligible(food,2,true,false) && !carrion.eligible({food.x,3,food.z},2,true,true),"living supported vertical physical contact");
 own.restoreState(.8,0,0,0,false);HeroSim hero;domain::HeroDrinkAutonomy controller;
 auto action=controller.update(hero,own,{food.x-6,2,food.z},1.5707963267948966,.1,false,food,true,false,needs::SuggestedActivity::Eat,carrion.resource);require(action.forward && hero.perception.attention()->source==211,"existing single food intention approaches carrion");action=controller.update(hero,own,{food.x-6,2,food.z},0,.1,true,food,true,false,needs::SuggestedActivity::Eat,211);require(!action.contact && !action.forward,"direct override");action=controller.update(hero,own,{food.x+32,2,food.z},0,.1,false,std::nullopt,false,false,needs::SuggestedActivity::Eat,211);require(!hero.perception.attention() && !action.active,"remote camera cannot grant food knowledge");
 std::vector<HabitatSite> sites{{{0,2,0},false,true,{1}},{{4,2,0},true,false,{0}}};Population population(42,1001,sites,8);ResourceLedgerDto history{{{100,ResourceKind::Creek,10,1},{200,ResourceKind::Shrub,10,1},{211,ResourceKind::Shrub,.8,0}},{{90,100,1},{91,200,1}}};std::uint64_t next=100;engine::NativePopulationRegistry host(population,history,{},{{0,100,sites[0].position},{1,200,sites[1].position}},next);const auto actors=host.snapshot();const auto bindings=host.sessions();
 InteractionsCore interactions(256);std::uint64_t lastSession=0;auto feed=[&](std::uint64_t session,double amount){if(session!=lastSession){interactions.beginSession(session);lastSession=session;}double available=1;if(host.consume(session,211,amount) && interactions.applyContact(session,211,true,amount,available)){own.feed(amount);return true;}return false;};
 require(feed(next++,.5) && std::abs(own.hunger()-.3)<1e-12,"actual finite contact and needs relief");const auto prior=own.hunger();require(!feed(next-1,.5) && own.hunger()==prior,"held session replay grants no second food or relief");require(std::abs(host.ledger().resources[2].consumedQuantity-.5)<1e-12 && carrion.fraction(.3)==.3,"actual partial visible fraction");require(feed(next++,.3) && own.hunger()<1e-12,"fresh session consumes exact finite remainder");bool refused=false;try{feed(next++,.1);}catch(const std::exception&){refused=true;}require(refused && host.ledger().resources[2].consumedQuantity==.8,"no invented food after depletion");
 require(host.sessions()==bindings && host.snapshot().actors[0].hunger==actors.actors[0].hunger && host.snapshot().actors.size()==8,"no NPC binding/reset or free relief");require(host.ledger().sessions[0].sessionId==90 && host.ledger().sessions[0].amount==1 && host.ledger().sessions[1].sessionId==91 && host.ledger().sessions[1].amount==1 && host.ledger().resources[0].consumedQuantity==1,"all old finite history preserved");
 StalthosState world(42);world.setHero(1,1);world.heroDied();std::vector<Identity> ids;for(const auto& a:host.actors())ids.push_back(a.id);const auto successor=domain::beginNextLife(world,1,ids,next);Lifecycle nextLife(domain::playableSpecies("Longstride"));needs::NeedsCore nextNeeds(nextLife.species());require(successor.hero!=1 && nextLife.species()==HeroSpecies::Longstride && nextNeeds.species()==HeroSpecies::Longstride && host.ledger().resources[2].consumedQuantity==.8,"same-species successor owns fresh components and retained depletion");
 std::cout<<"LONGSTRIDE_CARRION_OK actual fifth profile body-only single-goal finite accepted contact replay partial remainder history and successor\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
